if(!db.campusVersion){
 db.hostelName='The Campus House';db.decisions=[];db.deletedNotices=[];
 db.staff.forEach((s,i)=>s.id=i===0?'M-12':'M-'+(13+i));
 db.complaints.forEach(c=>{c.staffId=db.staff.find(s=>s.name===c.staff)?.id||'M-12';});
 db.visitors.forEach(v=>{v.managementStatus=v.status;v.status='Expected';v.contact=v.contact||'90000 03001';v.expectedExit=v.expectedExit||'18:00';});
 db.payments=[{id:'RCPT-26001',date:'2026-07-01',amount:25000,method:'Hostel office'},{id:'RCPT-26002',date:'2026-09-01',amount:15000,method:'Hostel office'}];
 db.campusVersion=1;saveData();
}
if(db.campusVersion<2){
 if(!db.feedback.length)db.feedback=[
 {student:'STU1025',rating:4,category:'Taste',comments:'Good dal today; a little less salt would help.',date:today()},
 {student:'STU1026',rating:5,category:'Hygiene',comments:'Dining area was clean and service was on time.',date:today()},
 {student:'STU1024',rating:4,category:'Menu',comments:'Would love a fruit option with breakfast.',date:today()}
 ];
 db.campusVersion=2;saveData();
}
let briefQuery='What needs attention?';
let briefMode='attention';
let briefDepth=0;
let briefRun=0;
let campusReportType='Outing history';
const lensButton=(text,action,style='')=>`<button type="button" class="btn ${style}" data-campus="${action}">${text}</button>`;
function campusLogo(){return `<span class="orbit-logo" aria-hidden="true"><svg viewBox="0 0 40 40"><path d="M32 29a15 15 0 1 1 2-15M12 29V17l8-6 8 6v12M17 29v-9h6v9"/><circle cx="34" cy="21" r="2"/></svg></span><span>HOSTEL<span class="logo-360">360</span></span>`;}
function campusArt(){return `<svg class="campus-art" viewBox="0 0 470 300" role="img" aria-label="A quiet courtyard and modern hostel building"><path d="M30 270h410M62 265V123l133-46v188M195 265V77l178 29v159" fill="#f7faff" stroke="#7c99e9" stroke-width="1.2"/><path d="m55 122 140-48 185 29M195 74v191" fill="none" stroke="#315efb" stroke-width="2"/><path d="M63 245 195 230l177 9v28H63z" fill="#d4dfff"/><path d="M218 263v-48q0-23 22-23t22 23v48" fill="#315efb"/><g fill="#b9caf8">${[0,1,2].map(r=>[0,1,2,3,4].map(c=>`<path d="m${213+c*29} ${120+r*28} 15 2v17l-15-1z"/>`).join('')).join('')}</g><g fill="#8da8ec">${[0,1,2].map(r=>[0,1,2,3].map(c=>`<path d="m${80+c*27} ${141+r*28-c*9} 14-4v17l-14 4z"/>`).join('')).join('')}</g><path d="M398 264V175M382 196q-18-29 6-38 16-31 30-4 30 21 5 42-17 17-41 0" fill="#bddbc8" stroke="#729b86"/><path d="M39 265v-58m-13 7q-13-20 4-28 13-18 23 0 19 20-3 32z" fill="#c9dfd4" stroke="#8bad9a"/><path d="M112 267v-33m0-14v-5m-6 22-8 14m14-14 12 11m-12 19-8 14m8-14 7 14" fill="none" stroke="#526b99" stroke-width="3" stroke-linecap="round"/><circle cx="112" cy="225" r="7" fill="#e8c4a0"/><circle cx="331" cy="42" r="24" fill="#f3ddb1"/><path d="M88 70h34m-19-5h29M387 77h35" stroke="#c2cbe1" stroke-width="2" stroke-linecap="round"/><path d="M125 286q116-18 212-5" fill="none" stroke="#9aafc8" stroke-dasharray="3 5"/></svg>`;}
function campusLogin(){
 $('#app').innerHTML=`<main class="login campus-login"><section class="login-story"><a class="brand" href="#login">${campusLogo()}</a><div class="login-editorial"><span class="eyebrow">CAMPUS LIFE, WELL CONNECTED</span><h1>A place to live.<br>A little more<br><span>room to be you.</span></h1><p>Everything you need for a simpler hostel experience.</p></div>${campusArt()}<p class="login-tagline">A smarter way to live, connect & manage.</p></section><section class="login-form"><span class="eyebrow">MAKE YOURSELF AT HOME</span><h1>Your day starts here.</h1><p class="subtitle">One home for your room, your plans, and your people.</p><form id="login-form">${field('Email / Student ID','username','text','STU1024','autocomplete="username"')}${field('Password','password','password','demo123','autocomplete="current-password"')}${select('Your space','role',['Student','Warden','Maintenance Staff'],localStorage.getItem('hostel360-remember-role')||'Student')}<div class="login-extras"><label><input type="checkbox" name="remember"> Remember my demo role</label><button type="button" data-campus="forgot">Forgot password?</button></div><button class="btn" type="submit">Login ${icon('arrow')}</button></form><div class="demo-hint"><span class="eyebrow">EXPLORE THE DEMO</span><p><strong>STU1024</strong> &nbsp;/&nbsp; demo123<br>Choose any role. All records are fictional.<br>Demo login only; no real authentication.</p></div><p class="login-footnote">Students. Wardens. Staff. One connected home.</p></section></main>`;
}
function friendlyGreeting(){const h=Number(localDateTime().slice(11,13));return h<12?'Good morning':h<17?'Good afternoon':'Good evening';}
function dashboardWelcome(name,sub){return `<header class="campus-welcome"><div><span class="eyebrow">${escapeHTML(db.hostelName)} / YOUR DAILY EDITION</span><h1>${friendlyGreeting()}, ${escapeHTML(name)} <span class="wave">👋</span></h1><p>${sub}</p></div><span class="edition">${new Date().toLocaleDateString('en-IN',{day:'2-digit',month:'short',timeZone:'Asia/Kolkata'})}<small>MAKE TODAY YOURS</small></span></header>`;}
function campusDashboard(){
 const r=db.rooms.find(r=>r.number===db.student.room),o=currentOuting();
 return dashboardWelcome(db.student.name,`Welcome back to ${escapeHTML(db.hostelName)}. Here’s what’s happening around your hostel today.`)+`<section class="home-spread"><div class="home-cover"><span class="eyebrow">THIS IS YOUR SPACE.</span><h2>A little less admin.<br><span>A lot more living.</span></h2><p>Good food, a familiar room, and your next adventure.<br>We’ll help with the details.</p><a href="#leave" class="cover-link">Where are you heading today? ${icon('arrow')}</a>${campusArt()}<span class="cover-caption">01 / THE GOOD PART OF CAMPUS LIFE</span></div><article class="room-pass"><div class="room-pass-top"><span class="eyebrow">MY ROOM</span>${icon('bed')}</div><strong class="room-number">${escapeHTML(r.number)}</strong><p>Floor ${r.floor} · Block ${r.block} · Bed ${escapeHTML(db.student.bed)}</p><span class="home-status"><i></i>${o?'Currently outside':'Checked in'}</span><div class="room-pass-bottom"><span class="avatars">${r.occupants.slice(0,3).map(n=>`<i>${initials(n)}</i>`).join('')}</span><span>${r.occupants.length} ${r.occupants.length===1?'person':'people'}. One little home.</span></div><a href="#room" class="btn secondary">View Room ${icon('arrow')}</a></article></section><nav class="home-shortcuts" aria-label="Quick actions">${[['01','leave','Outing','Make a plan','leave'],['02','tool','Complaint','Let’s get it fixed','complaint-new'],['03','visitors','Visitor','Good company, welcome','visitors'],['04','shield','Emergency','Help is always close','emergency']].map(([n,i,t,s,p])=>`<a href="#${p}" class="shortcut ${p==='emergency'?'safety-shortcut':''}"><span class="shortcut-number">${n}</span>${icon(i)}<span><strong>${t}</strong><small>${s}</small></span>${icon('arrow')}</a>`).join('')}</nav>${lensWorkspace()}<div class="daily-spread"><section class="today-menu"><span class="eyebrow">THE TABLE IS SET</span><h2>Good food.<br>Better company.</h2><div class="meal-editorial">${[['Breakfast','Poha, toast & chai','7:30–9 AM'],['Lunch','Dal tadka, roti & rice','12:30–2 PM'],['Snacks','Sandwich & masala chai','4:30–5:30 PM'],['Dinner','Paneer masala, rice & curd','7:30–9:30 PM']].map(([n,m,t],i)=>`<div><span>0${i+1}</span><section><strong>${n}</strong><p>${m}</p></section><small>${t}</small></div>`).join('')}</div><a href="#mess" class="cover-link">Rate today’s meal ${icon('arrow')}</a></section><section class="hostel-notes"><div class="section-title"><div><span class="eyebrow">ON THE NOTICE BOARD</span><h2>Around the house.</h2></div><a href="#notices">All notices ↗</a></div>${db.notices.slice(0,3).map((n,i)=>`<a class="editorial-notice" href="#notices"><span class="notice-date">${new Date(n.date+'T12:00:00').getDate()}<small>${new Date(n.date+'T12:00:00').toLocaleDateString('en-IN',{month:'short'})}</small></span><div><small>${escapeHTML(n.category)}</small><h3>${escapeHTML(n.title)}</h3><p>${escapeHTML(n.description)}</p></div>${icon('arrow')}</a>`).join('')}<div class="current-plan"><span class="eyebrow">MY OUTING / RIGHT NOW</span><p>${o?`${escapeHTML(o.destination)} · expected ${timeLabel(o.expected)}`:'You’re checked in. Your next plan starts here.'}</p><a href="#leave">${o?'View your outing pass':'Record an outing'} →</a></div></section></div>${livingBriefFooter()}`;
}
function lensWorkspace(){return `<section class="lens-workspace" aria-labelledby="lens-title"><div class="section-title"><div><span class="eyebrow"><span class="lens-symbol">⊙</span> HOSTEL LENS / YOUR EVERYDAY, IN FOCUS</span><h2 id="lens-title">Less searching.<br><span>More understanding.</span></h2></div><p>A question brings the right details together.<br><small>Local demo rules. No generative AI or external service.</small></p></div><form id="lens-form" class="lens-command"><span class="lens-symbol" aria-hidden="true">⊙</span><label class="sr-only" for="lens-question">Ask about your hostel records</label><input id="lens-question" name="question" value="${escapeHTML(briefQuery)}" placeholder="Ask about complaints, outings, fees or hostel life…" required maxlength="180"><button type="submit" aria-label="Explore this question">${icon('arrow')}</button></form><nav class="question-nav" aria-label="Explore by question">${['What needs attention?','Who is still outside?','What’s working?','Find something unexpected.'].map(q=>`<button data-campus="ask:${q}" class="${briefQuery===q?'selected':''}">${q}</button>`).join('')}</nav><div id="lens-result" aria-live="polite"></div></section>`;}
function deriveBrief(query){
 const q=query.toLowerCase();
 let mode=/unexpected|surprise|spare|room/.test(q)?'space':/outside|outing|return|late|movement|cutoff/.test(q)?'movement':/food|mess|meal|working|rating/.test(q)?'mess':/fee|paid|pay|balance/.test(q)?'fees':/notice|changed|happen|update/.test(q)?'notices':/attention|complaint|electrical|plumbing|cleaning|wi-fi|furniture|spark|urgent|focus|issue|fix|risk/.test(q)?'attention':'unknown';
 const room=(q.match(/\b[a-z]-\d{3}\b/i)||[])[0]?.toUpperCase();
 const category=['Electrical','Plumbing','Cleaning','Wi-Fi','Furniture','Mess'].find(c=>q.includes(c.toLowerCase()));
 let complaints=(role==='Maintenance Staff'?db.complaints.filter(c=>c.staff==='Rakesh Patel'):role==='Student'?db.complaints.filter(c=>c.student===db.student.id):db.complaints).filter(c=>/resolved|completed/.test(q)?c.status==='Resolved':c.status!=='Resolved');
 if(room)complaints=complaints.filter(c=>c.room===room);
 if(category)complaints=complaints.filter(c=>c.category===category);
 if(/emergency|urgent/.test(q))complaints=complaints.filter(c=>c.priority==='Emergency');
 else if(/high/.test(q))complaints=complaints.filter(c=>['Emergency','High'].includes(c.priority));
 const records=db.outings.filter(o=>role!=='Student'||o.student===db.student.id);
 const outside=records.filter(o=>!o.actual&&(!room||o.room===room));
 const overdue=outside.filter(o=>outingStatus(o)==='Overdue Return');
 const vacantBeds=db.rooms.reduce((n,r)=>n+r.capacity-r.occupants.length,0);
 const scope=role==='Student'?'your demo records':role==='Warden'?'the hostel demo register':'your assigned work';
 return {mode,room,category,complaints,records,outside,overdue,vacantBeds,scope};
}
function briefContent(b){
 if(b.mode==='attention'){
 const completed=/resolved|completed/.test(briefQuery.toLowerCase());
 const urgent=b.complaints.filter(c=>c.priority==='Emergency'&&c.status!=='Resolved');
 return {label:urgent.length?'ATTENTION / A SAFER HOME':b.complaints.length?'OBSERVATION / MAINTENANCE':'OBSERVATION / ALL CAUGHT UP',title:completed?'A fix, followed<br>all the way through.':urgent.length?'A small sign.<br>A serious priority.':b.complaints.length?'A few things<br>need a closer look.':'A little more<br>peace of mind.',summary:completed?`${b.complaints.length} matching completed complaint record(s). Open a timeline to see the recorded resolution status.`:urgent.length?`${urgent.length} open electrical or safety issue${urgent.length===1?' needs':'s need'} immediate attention. The description, priority and assignment are all connected below.`:b.complaints.length?`${b.complaints.length} matching open issue${b.complaints.length===1?'':'s'}. Follow the record to the person responsible and the next step.`:'No matching open complaints. Try a different room or explore your outing plans.',evidence:b.complaints.map(c=>({title:c.description,detail:`#${c.id} · ${c.room} · ${c.staff} · ${c.status}`,action:`complaint:${c.id}`,badge:c.priority})),layers:[`${b.complaints.length} matching complaint records. Every observation is grounded in the local register.`,`${urgent.length} marked Emergency. Routing uses keywords such as sparking, exposed wiring or gas leakage.`, 'Priority describes urgency. The complaint timeline records assignment and progress; it does not prove a repair has been completed.',role==='Warden'?'Open a complaint to review the description and confirm the right staff assignment.':'Open the complaint timeline to see its assigned staff and latest status.'],next:'Follow the work, not the worry.',href:'#complaints',action:'Open complaint tracker',metric:b.complaints.length,unit:'records worth a look',annotation:'Start with the evidence.',steps:[`Read ${db.complaints.length} complaint records`,`Matched ${b.complaints.length} records to your question`,`Identified ${urgent.length} emergency-priority records`,'Prepared the evidence and available actions']};
 }
 if(b.mode==='movement')return {label:'OBSERVATION / PLANS & PEOPLE',title:b.overdue.length?'A return time<br>needs a follow-up.':b.outside.length?'Out in the world.<br>Still in the loop.':'Everyone’s back.<br>Room to unwind.',summary:b.overdue.length?`${b.overdue.length} expected return time${b.overdue.length===1?' has':'s have'} passed without a check-in. This is a follow-up flag, not a violation.`:`${b.outside.length} open outing${b.outside.length===1?'':'s'} in ${b.scope}. Expected and actual return times keep the story clear.`,evidence:b.outside.map(o=>({title:o.destination,detail:`${o.id} · ${o.room} · expected ${dateTimeLabel(o.expected)}`,action:`outing:${o.id}`,badge:outingStatus(o)})),layers:[`${b.outside.length} records have a departure and no actual return.`,`${b.overdue.length} are overdue. The current ${db.demoClock?'demo':'real'} hostel clock is compared with each expected return.`, 'A missing check-in can have several explanations. The register cannot infer the student’s location or whether they broke a rule.',role==='Student'?'If you are back, record your actual return. If you need help, use the Emergency Hub.':'Review the outing details and follow your hostel’s contact procedure. No call or message is sent by this prototype.'],next:'What if the plan changes?',href:'#leave',action:role==='Student'?'Open my outing pass':'Open the outing register',metric:b.outside.length,unit:'currently outside',annotation:'An expected time, not a judgement.',steps:[`Read ${b.records.length} movement records`,`Found ${b.outside.length} open outings`,`Compared expected return times with hostel time`,'Prepared the register view']};
 if(b.mode==='space')return {label:'DISCOVERY / SOMETHING YOU DIDN’T ASK',title:'A little room<br>for possibility.',summary:`There are ${b.vacantBeds} spare beds across ${db.rooms.length} rooms in the demo register. Occupied rooms can still have space — room occupancy and bed occupancy tell different stories.`,evidence:db.rooms.map(r=>({title:`Room ${r.number}`,detail:`${r.occupants.length} people · ${r.capacity} beds · ${r.capacity-r.occupants.length} available`,href:role==='Warden'?'#rooms':'#room',badge:r.capacity>r.occupants.length?'Available':'Full'})),layers:[`${b.vacantBeds} beds are unoccupied in the demo room register.`,`${db.rooms.filter(r=>r.occupants.length>0&&r.occupants.length<r.capacity).length} occupied rooms still have spare beds. A room can be occupied without being full.`, 'Capacity is only one part of a room-change decision. Room type, preferences and hostel procedure still matter.',role==='Warden'?'Review room availability alongside pending room-change requests.':'See your room details or ask for a room change. Availability is not a confirmed allocation.'],next:'More space. Better decisions.',href:role==='Warden'?'#rooms':'#room',action:'Explore room availability',metric:b.vacantBeds,unit:'spare beds in the register',annotation:'Occupied ≠ full.',steps:[`Read ${db.rooms.length} room records`,'Compared capacity with current occupants',`Counted ${b.vacantBeds} spare beds`,'Prepared the availability explanation']};
 if(b.mode==='mess'){
 const n=db.feedback.length,avg=n?(db.feedback.reduce((a,f)=>a+f.rating,0)/n).toFixed(1):null;
 return {label:'OBSERVATION / A PLACE AT THE TABLE',title:n?'Small feedback.<br>Better everyday meals.':'A better meal<br>starts with your voice.',summary:n?`${n} meal feedback record${n===1?'':'s'}, averaging ${avg}/5. A small demo sample is a starting point, not a reliable trend.`:'There are no ratings yet. Today’s menu is ready; the next useful observation can start with your feedback.',evidence:db.feedback.slice(0,4).map(f=>({title:f.category,detail:`${f.rating}/5 · ${f.comments||'Rating only'}`,href:'#mess',badge:'Recorded'})),layers:[`${n} ratings recorded.`,n?`Average: ${avg}/5. Each submitted rating has equal weight.`:'No average is shown until a rating exists.','A rating alone does not explain food quality. Read the category and comments before deciding what to change.',role==='Student'?'Try today’s menu and leave a rating. Comments are optional.':'Review the feedback with the mess team and collect more responses before drawing conclusions.'],next:'Good food is a conversation.',href:'#mess',action:role==='Student'?'Rate today’s meal':'Review mess feedback',metric:avg||'—',unit:n?'average meal rating / 5':'your feedback can start here',annotation:'People before percentages.',steps:[`Read ${n} feedback records`,'Counted ratings and categories',n?'Calculated the simple mean':'Kept the average empty: no ratings yet','Prepared the menu and feedback view']};
 }
 if(b.mode==='fees'){const balance=db.fees.total-db.fees.paid;return {label:'OBSERVATION / ONE LESS THING TO REMEMBER',title:balance?'A little left.<br>A clear next step.':'All settled.<br>Enjoy the semester.',summary:`${money(db.fees.paid)} of ${money(db.fees.total)} is recorded as paid. ${balance?money(balance)+' remains, due '+prettyDate(db.fees.due)+'.':'There is no remaining balance.'} These are fictional demo amounts.`,evidence:db.payments.map(p=>({title:money(p.amount)+' recorded',detail:`${p.id} · ${prettyDate(p.date)} · ${p.method}`,href:'#fees',badge:'Paid'})),layers:[`Recorded balance: ${money(balance)}.`,`${Math.round(db.fees.paid/db.fees.total*100)}% of the total fee is recorded as paid.`,`Due date: ${prettyDate(db.fees.due)}. This interface does not collect money.`, 'Review your statement and contact the hostel accounts desk for the real payment procedure.'],next:'Know where you stand.',href:'#fees',action:'View fee statement',metric:money(balance),unit:'remaining in the demo ledger',annotation:'Always know what’s next.',steps:[`Read the fee record and ${db.payments.length} payment entries`,'Compared total fee with recorded payments','Calculated the remaining balance','Prepared the statement view']};}
 const n=db.notices[0];return {label:'OBSERVATION / AROUND THE HOUSE',title:'Something changed.<br>Here’s the note.',summary:n?n.description:'Your notice board is quiet. Check back for hostel updates.',evidence:db.notices.slice(0,3).map(n=>({title:n.title,detail:prettyDate(n.date)+' · '+n.category,href:'#notices',badge:'Notice'})),layers:[`${db.notices.length} current notices.`,n?'Latest published item: '+n.title:'No announcements are published.', 'Notice content comes from hostel management. No trend or prediction is inferred.', 'Read the complete notice and follow the applicable hostel instructions.'],next:'The useful details, together.',href:'#notices',action:'Read the notice board',metric:db.notices.length,unit:'hostel announcements',annotation:'A little context goes a long way.',steps:[`Read ${db.notices.length} notices`,'Selected recent announcements','Kept the original publication dates','Prepared the notice view']};
}
function briefEvidence(b,c){
 if(b.mode==='space')return `<div class="lens-capacity-map">${db.rooms.map(r=>`<a href="${role==='Warden'?'#rooms':'#room'}"><strong>${r.number}</strong><div>${Array.from({length:r.capacity},(_,i)=>`<span class="${i<r.occupants.length?'taken':''}" aria-label="${i<r.occupants.length?'Occupied bed':'Available bed'}"></span>`).join('')}</div><small>${r.capacity-r.occupants.length} available / ${r.capacity} beds</small></a>`).join('')}</div><p class="evidence-caption">Filled marks are occupied beds. Outlined marks are available beds.</p>`;
 if(b.mode==='movement'&&b.outside.length)return `<div class="lens-movement-timeline">${b.outside.slice(0,4).map(o=>`<button data-campus="outing:${o.id}"><small>${o.id} · ${escapeHTML(o.name)}</small><strong>${escapeHTML(o.destination)}</strong><div><span>${timeLabel(o.left)}<small>DEPARTURE</small></span><i aria-hidden="true">→</i><span>${timeLabel(o.expected)}<small>EXPECTED RETURN</small></span></div>${badge(outingStatus(o))}</button>`).join('')}</div>`;
 if(b.mode==='fees')return `<div class="ledger-proportion"><div><strong>${Math.round(db.fees.paid/db.fees.total*100)}%</strong><span>recorded as paid</span></div><div class="ledger-track" role="img" aria-label="${money(db.fees.paid)} of ${money(db.fees.total)} paid"><i style="width:${db.fees.paid/db.fees.total*100}%"></i></div><p>${money(db.fees.paid)} paid <span>${money(db.fees.total-db.fees.paid)} remaining</span></p></div>`+c.evidence.map(e=>`<a href="#fees" class="ledger-entry"><span>✓</span><div><strong>${escapeHTML(e.title)}</strong><small>${escapeHTML(e.detail)}</small></div></a>`).join('');
 return c.evidence.length?c.evidence.slice(0,4).map((e,i)=>`<${e.href?'a':'button'} ${e.href?`href="${e.href}"`:`data-campus="${e.action}"`} class="evidence-item"><span class="evidence-index">0${i+1}</span><div><strong>${escapeHTML(e.title)}</strong><small>${escapeHTML(e.detail)}</small></div>${badge(e.badge)}<span>↗</span></${e.href?'a':'button'}>`).join(''):`<div class="evidence-empty"><span>○</span><h4>A quiet register is a good place to begin.</h4><p>Open the module to explore or create a demo record.</p></div>`;
}
function mountBrief(){if(!$('#lens-result'))return;renderBrief(deriveBrief(briefQuery));}
function renderBrief(b){
 if(!$('#lens-result'))return;briefMode=b.mode;
 if(b.mode==='unknown'){$('#lens-result').innerHTML=`<div class="lens-recovery"><span class="eyebrow">LET’S FIND SOMETHING USEFUL</span><h3>I couldn’t match that to a hostel view.</h3><p>This simple prototype understands complaints, outings, rooms, mess, fees and notices. Try “Show electrical complaints in B-204” or choose a question above.</p>${lensButton('Show supported questions','help','secondary')}</div>`;return;}
 const c=briefContent(b);briefDepth=0;
 $('#lens-result').innerHTML=`<article class="investigation mode-${b.mode}"><div class="interpretation"><span>⊙ UNDERSTOOD: ${escapeHTML(b.mode==='space'?'Room capacity & available beds':b.mode)}</span><span>${b.room?'ROOM '+escapeHTML(b.room)+' / ':''}${b.category?escapeHTML(b.category)+' / ':''}${escapeHTML(b.scope)} · ${db.demoClock?'demo clock':'live local records'}</span></div><div class="research-spread"><section class="insight-story"><span class="eyebrow">${c.label}</span><h3>${c.title}</h3><p>${escapeHTML(c.summary)}</p><div class="insight-number">${c.metric}<span>${c.unit}</span></div><span class="margin-annotation">↳ ${c.annotation}</span></section><section class="evidence-column"><div class="evidence-heading"><span class="eyebrow">THE EVIDENCE</span>${lensButton('Watch the investigation','trace','text-button')}</div>${briefEvidence(b,c)}<a href="${c.href}" class="cover-link">${c.action} ${icon('arrow')}</a></section></div><div class="depth-control"><div><span class="eyebrow">SURFACE → UNDERSTANDING</span><span class="depth-count" id="depth-count">01 / 04</span></div><label for="lens-depth">Pull a little deeper.</label><input id="lens-depth" type="range" min="0" max="3" step="1" value="0" aria-describedby="depth-explanation"><div class="depth-ticks"><span>Observation</span><span>Evidence</span><span>Interpretation</span><span>Next step</span></div><p id="depth-explanation">${escapeHTML(c.layers[0])}</p></div><div class="decision-strip"><div><span class="eyebrow">WHAT SHOULD HAPPEN NEXT?</span><h4>${c.next}</h4></div><div>${b.mode==='movement'?lensButton('Simulate a return','simulate','secondary'):lensButton('Save to my focus','focus','secondary')}<a class="btn" href="${c.href}">${c.action} →</a></div></div></article>`;
}
function askLens(query){briefQuery=query;const input=$('#lens-question');if(input)input.value=query;const b=deriveBrief(query),run=++briefRun;const el=$('#lens-result');if(!el)return;el.innerHTML=`<div class="lens-processing" role="status"><span class="orbit-loader" aria-hidden="true"></span><div><span class="eyebrow">CHECKING THE LOCAL REGISTER</span><p>Reading relevant records and applying the demo rules.</p></div></div>`;document.querySelectorAll('.question-nav button').forEach(x=>x.classList.toggle('selected',x.textContent===query));setTimeout(()=>{if(run===briefRun&&$('#lens-result'))renderBrief(b);},window.matchMedia('(prefers-reduced-motion: reduce)').matches?0:300);}
function livingBriefFooter(){return `<section class="living-brief"><span>⊙</span><div><span class="eyebrow">YOUR LIVING HOSTEL BRIEF</span><p>New records change this brief. A new question changes the view.</p><small>${db.decisions.length?db.decisions.length+' item(s) saved to your focus.':'Nothing sent. Nothing automated. You stay in control.'}</small></div>${lensButton('Open my focus','focus-list','secondary')}</section>`;}
function campusWardenDashboard(){
 const n=movementCounts(db.outings),urgent=db.complaints.filter(c=>c.priority==='Emergency'&&c.status!=='Resolved'),alerts=db.emergencies.filter(e=>e.status!=='Resolved');
 const capacity=db.rooms.reduce((a,r)=>a+r.capacity,0),occupied=db.rooms.reduce((a,r)=>a+r.occupants.length,0);
 return dashboardWelcome('Kavita','A clear picture of the people, plans and small details that make a hostel work.')+`<section class="warden-editorial"><div><span class="eyebrow">THE DUTY DESK / TODAY</span><h2>Look after the people.<br><span>We’ll bring the details.</span></h2><p>${db.students.length} students call this place home. ${n.outside} ${n.outside===1?'is':'are'} currently outside, and ${activeComplaints().length} maintenance issues are still open.</p><a href="#leave" class="cover-link">Open the movement register ${icon('arrow')}</a></div><aside class="attention-queue"><span class="eyebrow">YOU SHOULD LOOK AT THESE</span>${alerts.length?`<a href="#emergency" class="attention-item critical"><small>EMERGENCY</small><strong>${alerts.length} SOS alert${alerts.length===1?' needs':'s need'} a response.</strong><span>Review the room and outing context ↗</span></a>`:''}${urgent.length?`<a href="#complaints" class="attention-item critical"><small>PRIORITY</small><strong>${urgent.length} emergency-priority complaint${urgent.length===1?' remains':'s remain'} open.</strong><span>Check assignment and work status ↗</span></a>`:''}<a href="#leave" class="attention-item"><small>${n.overdue?'FOLLOW UP':'MOVEMENT'}</small><strong>${n.overdue?n.overdue+' return time(s) need a follow-up.':n.outside+' student(s) are currently outside.'}</strong><span>Expected times are records, not violations ↗</span></a><a href="#rooms" class="attention-item"><small>OPPORTUNITY</small><strong>${capacity-occupied} spare beds across ${db.rooms.length} rooms.</strong><span>View availability and room-change requests ↗</span></a></aside></section><section class="occupancy-story"><div><span class="eyebrow">ROOM TO BELONG</span><h2>${occupied} people. ${capacity} beds.<br><span>${capacity-occupied} spaces for the next chapter.</span></h2></div><div><div class="weighted-rooms">${db.rooms.map(r=>`<a href="#rooms" aria-label="Room ${r.number}: ${r.occupants.length} of ${r.capacity} beds occupied"><span>${r.number}</span><div>${Array.from({length:r.capacity},(_,i)=>`<i class="${i<r.occupants.length?'filled':''}"></i>`).join('')}</div><small>${r.occupants.length}/${r.capacity}</small></a>`).join('')}</div><p>● Occupied bed &nbsp; ○ Available bed <span>Room occupancy and bed occupancy are different measures.</span></p></div></section>${lensWorkspace()}${wardenMovementSection()}<div class="admin-actions"><a class="btn" href="#reports">Generate a hostel report →</a>${btn('Publish a notice','add-notice','secondary','plus')}<a class="btn secondary" href="#staff">Manage maintenance team →</a></div>${livingBriefFooter()}`;
}
function campusWorkCenter(){const assigned=db.complaints.filter(c=>c.staff==='Rakesh Patel'),open=assigned.filter(c=>c.status!=='Resolved');return dashboardWelcome('Rakesh','One clear list. The right priority. A better place to live.')+`<section class="work-intro"><span class="eyebrow">WORK CENTER / ELECTRICAL MAINTENANCE / M-12</span><h2>Small fixes.<br><span>A big difference.</span></h2><p>${open.length} open assignment${open.length===1?'':'s'} · ${assigned.filter(c=>c.status==='Resolved').length} completed</p></section>${[['Immediate attention',['Emergency','High']],['Next in line',['Medium']],['Routine care',['Low']]].map(([title,priorities])=>`<section class="work-lane"><div class="section-title"><h2>${title}</h2><span class="eyebrow">${open.filter(c=>priorities.includes(c.priority)).length} ASSIGNMENTS</span></div>${open.filter(c=>priorities.includes(c.priority)).map(c=>`<article class="work-row"><div class="work-room">${escapeHTML(c.room)}</div><div><span class="eyebrow">#${c.id} / ${escapeHTML(c.category)}</span><h3>${escapeHTML(c.description)}</h3><span class="helper">${escapeHTML(c.staff)} · ${escapeHTML(c.staffId||'M-12')}</span><button class="text-link" data-action="detail:${c.id}">View timeline →</button></div><div class="work-status">${badge(c.priority)} ${badge(c.status)}${staffButtons(c)}</div></article>`).join('')||'<p class="calm-empty">All clear here. The next relevant assignment will appear in this lane.</p>'}</section>`).join('')}<a href="#complaint-history" class="cover-link">See completed work ${icon('arrow')}</a>`;}
function campusComplaintHistory(){return heading('The work that made a difference.','Your completed maintenance assignments.')+panel('Complaint history',table(['Complaint','Room','Priority','Reported','Assigned staff','Status',''],complaintRows(db.complaints.filter(c=>c.staff==='Rakesh Patel'&&c.status==='Resolved'))));}
function campusSettings(){return heading('A hostel with its own rhythm.','Set the name, outing hours and procedures that fit your hostel.')+panel('Hostel identity',body(`<form id="campus-settings-form"><div class="form-grid">${field('Hostel name','hostelName','text',db.hostelName,'maxlength="60"')}<div class="field"><span>Regular outing hours</span><strong>${hoursLabel()}</strong></div></div><div class="form-actions">${moveButton('Edit timings & procedures','rules','secondary')}<button class="btn">Save hostel name</button></div></form>`))+panel('Your current movement policy',body(`<div class="detail-list"><div><small>Normal outings</small><strong>No special permission within ${hoursLabel()}</strong></div><div><small>Special / Late outings</small><strong>${escapeHTML(db.hostelTiming.specialProcess)}</strong></div><div><small>Extended leave</small><strong>${escapeHTML(db.hostelTiming.leaveProcess)}</strong></div><div><small>Responsible authority</small><strong>${escapeHTML(db.hostelTiming.authority)}</strong></div></div><p class="helper top-gap">Existing requests keep the procedure recorded at submission. All changes stay in this browser’s demo data.</p>`))+panel('Try a change before making it',body('<p class="helper">Compare a proposed return cutoff against the recorded normal outings. The simulation does not change hostel rules until you explicitly apply it.</p>'+lensButton('Simulate an outing cutoff','policy-sim','secondary')));}
function roomAmenities(){return panel('Made for everyday living',body(`<div class="room-amenities">${[['Wi-Fi','Study, stream, stay connected.'],['Study desk','A corner for your next good idea.'],['Storage & bed','Your essentials, in their place.'],['Shared bathroom','Common facilities on this floor.']].map(([a,b])=>`<div><span>○</span><strong>${a}</strong><p>${b}</p></div>`).join('')}</div><div class="room-rules"><h3>A few shared-house habits.</h3><p>Observe quiet hours after 10 PM. Keep common spaces clean. Record your return and follow the outing procedure shown in your hostel settings.</p><a href="#complaints">View room maintenance requests →</a></div>`));}
function paymentHistory(){return panel('Payment history · demo ledger',table(['Receipt','Date','Recorded payment','Method'],db.payments.map(p=>`<tr><td>${p.id}</td><td>${prettyDate(p.date)}</td><td>${money(p.amount)}</td><td>${p.method}</td></tr>`)));}
function campusVisitorRows(){return db.visitors.map(v=>`<tr><td><strong>${v.id}</strong><span class="table-sub">${escapeHTML(v.relationship)}</span></td><td>${escapeHTML(v.name)}<span class="table-sub">${escapeHTML(v.contact)} · Demo number</span></td><td>${prettyDate(v.date)} · ${escapeHTML(v.time)}<span class="table-sub">Expected exit: ${escapeHTML(v.expectedExit)}</span></td><td style="white-space:normal">${escapeHTML(v.purpose)}</td><td>${badge(v.status)}<span class="table-sub">Management: ${escapeHTML(v.managementStatus||'Recorded')}</span></td><td>${role==='Warden'?`${v.status==='Expected'?lensButton('Record entry','visitor-enter:'+v.id,'small secondary'):v.status==='Inside'?lensButton('Record exit','visitor-exit:'+v.id,'small secondary'):''}${v.status==='Expected'&&v.managementStatus!=='Approved'?' '+lensButton('Approve','visitor-approve:'+v.id,'small secondary')+' '+lensButton('Reject','visitor-reject:'+v.id,'small secondary'):''}`:''}</td></tr>`);}
function campusVisitors(){return heading('Good company, welcome.','A visit feels simpler when everyone knows the plan.')+(role==='Student'?panel('Register a visitor',body(`<form id="campus-visitor-form"><div class="form-grid">${field('Visitor name','name')}${select('Relationship','relationship',['Parent','Sibling','Relative','Friend','Other'])}${field('Contact · demo number','contact','tel','','pattern="[0-9+ ()-]{10,16}"')}${field('Date','date','date',movementDay())}${field('Entry time','time','time','16:00')}${field('Expected exit','expectedExit','time','18:00')}${field('Purpose','purpose','textarea')}</div><div class="form-actions"><button class="btn">Register Visitor</button></div></form>`)):'')+panel(role==='Student'?'Your visitors':'Visitor register',table(['Visitor ID','Visitor / contact','Visit schedule','Purpose','Status','Action'],campusVisitorRows()));}
function campusNotices(){return heading('A note for everyone.','The useful things to know about life around the house.',role==='Warden'?btn('Add Notice','add-notice','','plus'):'')+`<div class="notice-editorial-grid">${db.notices.map((n,i)=>`<article class="notice-sheet"><div class="notice-sheet-meta"><span>${escapeHTML(n.category)}</span><span>${prettyDate(n.date)}</span></div><span class="sheet-mark">${i===0?'↗':'○'}</span><h2>${escapeHTML(n.title)}</h2><p>${escapeHTML(n.description)}</p><div class="notice-sheet-bottom"><span>HOSTEL360 / COMMUNITY NOTE</span>${role==='Warden'?`<div>${lensButton('Edit','notice-edit:'+n.id,'small secondary')}${lensButton('Delete','notice-delete:'+n.id,'small secondary')}</div>`:''}</div></article>`).join('')}</div>`+(role==='Warden'&&db.deletedNotices.length?`<div class="form-actions">${lensButton('Restore last deleted notice','notice-restore','secondary')}</div>`:'');}
function editNotice(id){const n=db.notices.find(n=>n.id===id);if(!n||role!=='Warden')return;openModal(`<h2>Edit community notice</h2><form id="campus-notice-form" data-id="${n.id}"><div class="form-grid">${field('Title','title','text',n.title)}${select('Category','category',['General','Maintenance','Mess Update','Holiday','Water Supply'],n.category)}${field('Description','description','textarea',n.description)}</div><div class="form-actions"><button class="btn">Save notice</button></div></form>`);}
function campusOutingPass(){const o=currentOuting();if(!o)return '';return `<section class="digital-pass"><div class="pass-main"><span class="eyebrow">HOSTEL360 / DIGITAL OUTING PASS</span><h2>${escapeHTML(o.destination)}</h2><p>${escapeHTML(o.name)} · Room ${escapeHTML(o.room)}</p><div class="pass-details"><div><small>Leaving</small><strong>${dateTimeLabel(o.left)}</strong></div><div><small>Expected return</small><strong>${dateTimeLabel(o.expected)}</strong></div><div><small>Reason</small><strong>${escapeHTML(o.reason)}</strong></div><div><small>Current status</small>${badge(outingStatus(o))}</div></div>${outingStatus(o)==='Overdue Return'?`<p class="orange-text helper">${delayMinutes(o)} minutes past expected return. A record for management attention; no violation is assumed.</p>`:''}</div><div class="pass-stub"><span class="pass-orbit">⊙</span><span class="eyebrow">YOUR OUTING ID</span><strong>${o.id}</strong><span class="helper">${escapeHTML(o.type)} outing<br>Room recorded · No GPS</span>${moveButton('Record Return','return:'+o.id)}${moveButton('View details','outing:'+o.id,'secondary small')}</div></section>`;}
function campusReportsPage(){const menu=panel('Choose a report',body(select('Report type','reportType',['Outing history','Late return summary','Student list','Room occupancy','Complaint summary','Complaint resolution time','Visitor history','Fee summary','Mess feedback'],campusReportType)));if(campusReportType==='Outing history')return menu+reportsPage();return heading('The useful details. Ready to share.','Simple, printable records from your local hostel demo.')+menu+simpleCampusReport(campusReportType);}
function simpleCampusReport(type){let headers=[],rows=[];
 if(type==='Student list'){headers=['Student','ID','Course','Year','Room'];rows=db.students.map(s=>[s.name,s.id,s.course,s.year,s.room]);}
 if(type==='Room occupancy'){headers=['Room','Capacity','Occupants','Available'];rows=db.rooms.map(r=>[r.number,r.capacity,r.occupants.length,r.capacity-r.occupants.length]);}
 if(type==='Complaint summary'){headers=['ID','Room','Category','Priority','Staff','Status'];rows=db.complaints.map(c=>[c.id,c.room,c.category,c.priority,c.staff,c.status]);}
 if(type==='Complaint resolution time'){headers=['ID','Status','Reported','Resolved','Elapsed'];rows=db.complaints.map(c=>[c.id,c.status,c.createdAt?dateTimeLabel(c.createdAt):prettyDate(c.date),c.resolvedAt?dateTimeLabel(c.resolvedAt):'Not recorded',c.createdAt&&c.resolvedAt?Math.max(0,Math.round((new Date(c.resolvedAt)-new Date(c.createdAt))/60000))+' min':'Not recorded']);}
 if(type==='Visitor history'){headers=['Visitor ID','Name','Date','Entry','Exit','Status'];rows=db.visitors.map(v=>[v.id,v.name,v.date,v.actualEntry?dateTimeLabel(v.actualEntry):'Not recorded',v.actualExit?dateTimeLabel(v.actualExit):'Not recorded',v.status]);}
 if(type==='Fee summary'){headers=['Student','Total','Paid','Pending','Due'];rows=[[db.student.name,money(db.fees.total),money(db.fees.paid),money(db.fees.total-db.fees.paid),prettyDate(db.fees.due)]];}
 if(type==='Mess feedback'){headers=['Date','Rating','Category','Comment'];rows=db.feedback.map(f=>[f.date,f.rating+'/5',f.category,f.comments||'Rating only']);}
 if(type==='Late return summary'){headers=['Outing','Student','Room','Destination','Expected','Actual','Late by'];rows=db.outings.filter(o=>o.actual&&outingStatus(o)==='Late Return').map(o=>[o.id,o.name,o.room,o.destination,dateTimeLabel(o.expected),dateTimeLabel(o.actual),delayMinutes(o)+' min']);}
 return `<div id="movement-report"><section class="print-report panel"><div class="panel-head"><div><span class="eyebrow">HOSTEL360 / REGISTER REPORT</span><h2>${type}</h2></div>${moveButton('Print / Save as PDF','print','secondary')}</div><div class="panel-body"><p class="helper">${escapeHTML(db.hostelName)} · Generated ${dateTimeLabel(movementNow())} IST · Fictional local records</p></div>${table(headers,rows.map(row=>'<tr>'+row.map(cell=>'<td>'+escapeHTML(cell)+'</td>').join('')+'</tr>'))}</section></div>`;
}
function showReturnSimulation(){
 const o=currentOuting();openModal(`<span class="eyebrow">◇ A WHAT-IF, NOT A PREDICTION</span><h2>What if you return later?</h2><p class="helper">${o?`Using ${o.id} · ${escapeHTML(o.destination)}. Expected return: ${dateTimeLabel(o.expected)}.`:'No active outing. Explore a hypothetical outing with an expected return one hour from now.'} This does not update the register.</p><label class="field" for="return-sim-minutes">Return in <strong id="return-sim-label">30 minutes</strong></label><input id="return-sim-minutes" type="range" min="0" max="180" step="5" value="30"><div id="return-sim-result" class="simulation-result" aria-live="polite"></div><div class="form-actions"><a href="#leave" class="btn" data-action="close">Open Outing & Leave →</a></div>`);updateReturnSimulation();
}
function updateReturnSimulation(){const input=$('#return-sim-minutes');if(!input)return;const m=Number(input.value),o=currentOuting();const at=new Date(movementNow().getTime()+m*60000),expected=o?new Date(o.expected):new Date(movementNow().getTime()+3600000),late=Math.max(0,Math.ceil((at-expected)/60000));$('#return-sim-label').textContent=m+' minutes';$('#return-sim-result').innerHTML=`<span class="eyebrow">HYPOTHETICAL CHECK-IN</span><strong>${timeLabel(at)}</strong>${badge(late?'Late Return':'Returned On Time')}<p>${late?`That would be ${late} minutes after the expected return.`:'That would be within the expected return time.'}</p><small>Only arithmetic on demo timestamps. No location, forecast or penalty.</small>`;}
function cutoffImpact(end){return db.outings.filter(o=>o.type==='Normal').filter(o=>{
 const start=minutesOf(db.hostelTiming.start),finish=minutesOf(end),leave=minutesOf(localDateTime(o.left).slice(11));
 const within=start<finish?leave>=start&&leave<finish:leave>=start||leave<finish;
 let cutoff=parseHostelTime(movementDay(o.left)+'T'+end);if(start>finish&&leave>=start)cutoff=new Date(cutoff.getTime()+86400000);
 return !within||new Date(o.expected)>cutoff;
});}
function showPolicySimulation(){if(role!=='Warden')return;openModal(`<span class="eyebrow">◇ TEST THE RULE, BEFORE THE CHANGE</span><h2>A different rhythm?</h2><p class="helper">Compare a proposed regular return cutoff with recorded normal outings. Existing records and procedures stay intact.</p>${field('Proposed regular end time','end','time',db.hostelTiming.end,'id="policy-end"')}<div id="policy-sim-result" class="simulation-result" aria-live="polite"></div><p class="helper">This is a historical comparison, not a forecast of student behaviour. Applying the change affects new outings only.</p><div class="form-actions">${lensButton('Apply this cutoff','apply-policy')}</div>`);updatePolicySimulation();}
function updatePolicySimulation(){const end=$('#policy-end')?.value;if(!end)return;const impact=cutoffImpact(end);$('#policy-sim-result').innerHTML=`<span class="eyebrow">RECORDED NORMAL OUTINGS OUTSIDE THIS PROPOSED WINDOW</span><strong>${impact.length} <small>/ ${db.outings.filter(o=>o.type==='Normal').length}</small></strong><p>${impact.length?'These records would have needed the special outing procedure under this proposed window.':'Every recorded normal outing fits this proposed window.'}</p>${impact.slice(0,3).map(o=>`<small>${o.id} · left ${timeLabel(o.left)} · expected ${timeLabel(o.expected)}</small>`).join('')}`;}
document.addEventListener('input',e=>{
 if(e.target.id==='lens-depth'){
  const b=deriveBrief(briefQuery),c=briefContent(b);briefDepth=Number(e.target.value);$('#depth-count').textContent='0'+(briefDepth+1)+' / 04';$('#depth-explanation').textContent=c.layers[briefDepth];$('.investigation').dataset.depth=briefDepth;
 }
 if(e.target.id==='return-sim-minutes')updateReturnSimulation();
 if(e.target.id==='policy-end')updatePolicySimulation();
});
document.addEventListener('change',e=>{if(e.target.name==='reportType'){campusReportType=e.target.value;render();}});
document.addEventListener('click',e=>{
 const t=e.target.closest('[data-campus]');if(!t)return;const [action,id]=t.dataset.campus.split(':');
 if(action==='ask')askLens(id);
 if(action==='complaint')showComplaint(id);
 if(action==='outing')showOuting(id);
 if(action==='simulate')showReturnSimulation();
 if(action==='policy-sim')showPolicySimulation();
 if(action==='apply-policy'&&role==='Warden'){const end=$('#policy-end').value;if(!/^\d{2}:\d{2}$/.test(end)){toast('Choose a valid cutoff time.');return;}if(end===db.hostelTiming.start){toast('Start and end must be different. Choose another cutoff.');return;}db.hostelTiming.end=end;finishMovement('New regular outing cutoff saved. Existing records are unchanged.');}
 if(action==='trace'){
  const b=deriveBrief(briefQuery),c=briefContent(b);openModal(`<span class="eyebrow">⊙ WATCH THE RECORDS COME INTO FOCUS</span><h2>Here’s what was checked.</h2><ol class="investigation-trace">${c.steps.map((step,i)=>`<li><span>0${i+1}</span><div><strong>${escapeHTML(step)}</strong><small>✓ Completed using local demo records</small></div></li>`).join('')}</ol><div class="trace-conclusion"><strong>No hidden process. No invented certainty.</strong><p class="helper">These are observable data operations. The prototype matches keywords and computes counts. It does not infer causes, verify safety or predict behaviour.</p></div>`);
 }
 if(action==='focus'){
  if(!db.decisions.some(d=>d.query===briefQuery&&d.role===role&&!d.done))db.decisions.unshift({id:'FOCUS-'+Date.now(),query:briefQuery,role,date:new Date().toISOString(),done:false});
  saveData();toast('Saved to your focus. No message or automated action was sent.');
 }
 if(action==='focus-list'){const list=db.decisions.filter(d=>d.role===role);openModal(`<span class="eyebrow">→ YOUR FOCUS / YOU DECIDE THE NEXT STEP</span><h2>A few things to come back to.</h2>${list.map(d=>`<div class="focus-row"><strong>${escapeHTML(d.query)}</strong><small>${prettyDate(movementDay(d.date))} · ${d.done?'Completed':'Saved for review'}</small>${!d.done?lensButton('Mark done','focus-done:'+d.id,'small secondary'):badge('Completed')}</div>`).join('')||'<p class="helper">Nothing saved yet. Explore a hostel question and save the next useful action.</p>'}`);}
 if(action==='focus-done'){const d=db.decisions.find(d=>d.id===id&&d.role===role);if(d){d.done=true;saveData();t.outerHTML=badge('Completed');toast('Focus item completed.');}}
 if(action==='help')openModal(`<h2>What would you like to understand?</h2><p class="helper">Try: “Show electrical complaints in B-204”, “Who is still outside?”, “Show my fee balance”, “What changed?”, or “Find something unexpected”. The interface selects a focused view using simple keywords.</p>`);
 if(action==='forgot')openModal('<h2>A demo, without password worries.</h2><p>This prototype uses <strong>STU1024 / demo123</strong> for every role. There is no real password to reset and no reset email will be sent.</p>');
 if(action==='notice-edit')editNotice(id);
 if(action==='notice-delete'&&role==='Warden'){const n=db.notices.find(n=>n.id===id);if(n)openModal(`<h2>Remove this notice?</h2><p>${escapeHTML(n.title)}</p><p class="helper">You can restore the last deleted notice from the notice board.</p><div class="form-actions">${btn('Cancel','close','secondary')}${lensButton('Delete notice','notice-confirm:'+n.id)}</div>`);}
 if(action==='notice-confirm'&&role==='Warden'){const n=db.notices.find(n=>n.id===id);if(n){db.deletedNotices.push(n);db.notices=db.notices.filter(n=>n.id!==id);finishMovement('Notice removed. Restore is available on the notice board.');}}
 if(action==='notice-restore'&&role==='Warden'&&db.deletedNotices.length){db.notices.unshift(db.deletedNotices.pop());saveData();render();toast('Notice restored.');}
 if(action.startsWith('visitor-')&&role==='Warden'){
  const v=db.visitors.find(v=>v.id===id);if(!v)return;
  if(action==='visitor-approve')v.managementStatus='Approved';
  if(action==='visitor-reject')v.managementStatus='Rejected';
  if(action==='visitor-enter'){
   if(v.status!=='Expected')return;
   if(v.managementStatus==='Rejected'){toast('This visit was rejected by management. Review the decision before entry.');return;}
   v.status='Inside';v.actualEntry=movementNow().toISOString();
  }
  if(action==='visitor-exit'){if(v.status!=='Inside')return;v.status='Exited';v.actualExit=movementNow().toISOString();}
  saveData();render();toast('Visitor record updated.');
 }
});
document.addEventListener('submit',e=>{
 const form=e.target;if(!['lens-form','campus-settings-form','campus-visitor-form','campus-notice-form'].includes(form.id))return;
 e.preventDefault();e.stopImmediatePropagation();const d=Object.fromEntries(new FormData(form));
 if(form.id==='lens-form'){askLens(d.question.trim());return;}
 if(form.id==='campus-settings-form'&&role==='Warden'){
  if(!d.hostelName.trim()){toast('Give your hostel a name.');return;}db.hostelName=d.hostelName.trim();saveData();render();toast('Hostel identity saved.');
 }
 if(form.id==='campus-notice-form'&&role==='Warden'){
  const n=db.notices.find(n=>n.id===form.dataset.id);if(!n)return;if(!d.title.trim()||!d.description.trim()){toast('Add a title and description.');return;}Object.assign(n,d);n.updatedAt=new Date().toISOString();finishMovement('Community notice updated.');
 }
 if(form.id==='campus-visitor-form'&&role==='Student'){
  if(d.date<movementDay()){toast('Choose today or a future visit date.');return;}
  if(d.expectedExit<=d.time){toast('Expected exit must be after entry on the visit date.');return;}
  if(!d.name.trim()||!d.purpose.trim()){toast('Add the visitor name and purpose.');return;}
  const id='VIS-'+(3001+db.visitors.length);db.visitors.unshift({...d,id,student:db.student.id,status:'Expected',managementStatus:'Pending'});saveData();render();success('Your visitor is on the list.',`<p><strong>${id}</strong> · ${badge('Expected')}</p><p>${escapeHTML(d.name)} · ${prettyDate(d.date)}<br>${escapeHTML(d.time)}–${escapeHTML(d.expectedExit)}</p><p class="helper">Management can review the visit and record entry and exit. No external message is sent.</p>`);
 }
},true);

document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.querySelector('.sidebar.open')){document.querySelector('.sidebar').classList.remove('open');document.querySelector('.mobile-shade').classList.remove('open');const button=document.querySelector('.menu-toggle');button.setAttribute('aria-expanded','false');button.focus();}});
